sp_widget.client_script:
api.spinner = true;
api.server.get().then(function(response) {
    api.data.feedback = response.data.result || [];
    api.spinner = false;
});

sp_widget.script:
(function() {
    data.result = [];
    try {
        var gr = new GlideRecord('x_1850353_employ_0_employee_feedback');
        gr.orderByDesc('sys_created_on');
        gr.setLimit(50);
        gr.query();
        while (gr.next()) {
            data.result.push({
                sys_id: gr.getUniqueValue(),
                employee: gr.getDisplayValue('employee'),
                category: gr.getDisplayValue('category'),
                rating: gr.getDisplayValue('rating'),
                comments: gr.getDisplayValue('comments'),
                status: gr.getDisplayValue('status'),
                submitted_on: gr.getDisplayValue('submitted_on')
            });
        }
    } catch(e) {
        gs.error('Feedback widget error: ' + e.message);
    }
})();
